CREATE TABLE IF NOT EXISTS professional_market_profiles (id serial PRIMARY KEY,user_id integer NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,profile_kind varchar(24) NOT NULL,profession_code varchar(64) NOT NULL,sector_codes jsonb NOT NULL DEFAULT '[]',country_code varchar(2) NOT NULL,city varchar(120),years_experience integer NOT NULL DEFAULT 0,skills jsonb NOT NULL DEFAULT '[]',summary text,cv_url text,motivation_letter_url text,diplomas jsonb NOT NULL DEFAULT '[]',certifications jsonb NOT NULL DEFAULT '[]',supporting_documents jsonb NOT NULL DEFAULT '[]',travel_radius_km integer NOT NULL DEFAULT 0,availability jsonb NOT NULL DEFAULT '[]',status varchar(24) NOT NULL DEFAULT 'draft',review_note text,reviewed_by integer REFERENCES users(id),reviewed_at timestamp,submitted_at timestamp,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS professional_market_profiles_status_idx ON professional_market_profiles(status);
CREATE TABLE IF NOT EXISTS professional_missions (id serial PRIMARY KEY,reference varchar(32) NOT NULL UNIQUE,company_user_id integer NOT NULL REFERENCES users(id),company_name varchar(190) NOT NULL,sector_code varchar(64) NOT NULL,profession_codes jsonb NOT NULL DEFAULT '[]',mission_type varchar(24) NOT NULL DEFAULT 'mission',title varchar(190) NOT NULL,description text NOT NULL,country_code varchar(2) NOT NULL,currency varchar(4) NOT NULL,city varchar(120) NOT NULL,remote_allowed boolean NOT NULL DEFAULT false,start_date timestamp,end_date timestamp,slots jsonb NOT NULL DEFAULT '[]',headcount integer NOT NULL DEFAULT 1,experience_min_years integer NOT NULL DEFAULT 0,required_skills jsonb NOT NULL DEFAULT '[]',rate_min numeric(14,2),rate_max numeric(14,2),rate_unit varchar(16) NOT NULL DEFAULT 'day',pricing jsonb,visibility varchar(12) NOT NULL DEFAULT 'public',status varchar(24) NOT NULL DEFAULT 'draft',published_at timestamp,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS professional_missions_company_idx ON professional_missions(company_user_id,status);
CREATE INDEX IF NOT EXISTS professional_missions_public_idx ON professional_missions(status,country_code,sector_code);
CREATE TABLE IF NOT EXISTS professional_mission_applications (id serial PRIMARY KEY,reference varchar(32) NOT NULL UNIQUE,mission_id integer NOT NULL REFERENCES professional_missions(id) ON DELETE CASCADE,professional_user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,message text,requested_rate numeric(14,2),status varchar(24) NOT NULL DEFAULT 'mka_review',mka_review_note text,reviewed_by integer REFERENCES users(id),reviewed_at timestamp,shared_to_company_at timestamp,company_decision_note text,decided_at timestamp,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),CONSTRAINT professional_mission_applications_applicant_uidx UNIQUE(mission_id,professional_user_id));
CREATE INDEX IF NOT EXISTS professional_mission_applications_mission_idx ON professional_mission_applications(mission_id,status);
CREATE TABLE IF NOT EXISTS professional_work_orders (id serial PRIMARY KEY,reference varchar(32) NOT NULL UNIQUE,mission_id integer NOT NULL UNIQUE REFERENCES professional_missions(id),application_id integer NOT NULL REFERENCES professional_mission_applications(id),company_user_id integer NOT NULL REFERENCES users(id),professional_user_id integer NOT NULL REFERENCES users(id),amount numeric(14,2),currency varchar(4) NOT NULL,terms jsonb NOT NULL DEFAULT '{}',status varchar(24) NOT NULL DEFAULT 'issued',issued_at timestamp NOT NULL DEFAULT now(),accepted_at timestamp,started_at timestamp,completed_at timestamp);